 11	import json
 12	import os
 13	from pathlib import Path
 14	
 15	SECRET_HINTS = ("KEY", "TOKEN", "SECRET", "PASSWORD", "CREDENTIAL")
 16	INTERESTING_DIRS = ("tests", "test", "e2e", "test-e2e", "playwright", "specs", "spec")
 17	
 18	
 19	def _redact(name: str, value: str) -> str:
 20	    if any(hint in name.upper() for hint in SECRET_HINTS):
 21	        return f"<set:{len(value)} chars>" if value else "<empty>"
 22	    return value[:400]
 23	
 24	
 25	def environment_snapshot() -> dict[str, object]:
 26	    env = {name: _redact(name, value) for name, value in sorted(os.environ.items())}
 27	    return {
 28	        "argv": list(os.sys.argv),
 29	        "cwd": str(Path.cwd()),
 30	        "python": os.sys.version,
 31	        "platform": os.sys.platform,
 32	        "env": env,
 33	        "arcbench_env": {
 34	            name: _redact(name, os.environ.get(name, ""))
 35	            for name in (
 36	                "MODEL",
 37	                "OPENAI_BASE_URL",
 38	                "ARCBENCH_TASK_DIR",
 39	                "ARCBENCH_OUTPUT_DIR",
 40	                "ARCBENCH_TASK_TYPE",
 41	                "ARCBENCH_TRACEABILITY_DIR",
 42	                "ARCBENCH_AGENT_MODE",
 43	                "PORT",
 44	            )
 45	        },
 46	    }
 47	
 48	
 49	def _tree(root: Path, depth: int = 2, limit: int = 60) -> list[str]:
 50	    out: list[str] = []
 51	    if not root.is_dir():
 52	        return out
 53	
 54	    def walk(directory: Path, level: int) -> None:
 55	        if level > depth or len(out) >= limit:
 56	            return
 57	        try:
 58	            entries = sorted(directory.iterdir(), key=lambda p: (p.is_file(), p.name))
 59	        except OSError:
 60	            return
 61	        for entry in entries:
 62	            if len(out) >= limit:
 63	                return
 64	            if entry.name in {"node_modules", ".git", "__pycache__"}:
 65	                continue
 66	            suffix = "/" if entry.is_dir() else ""
 67	            out.append(f"{entry.relative_to(root).as_posix()}{suffix}")
 68	            if entry.is_dir():
 69	                walk(entry, level + 1)
 70	
 71	    walk(root, 1)
 72	    return out
 73	
 74	
 75	def directory_recon(output_dir: Path, requirements_dir: Path) -> dict[str, object]:
 76	    roots: dict[str, object] = {}
 77	    for label, path in (
 78	        ("cwd", Path.cwd()),
 79	        ("output", output_dir),
 80	        ("output_parent", output_dir.parent),
 81	        ("requirements", requirements_dir),
 82	        ("requirements_parent", requirements_dir.parent),
 83	        ("root", Path("/")),
 84	    ):
 85	        roots[label] = {"path": str(path), "exists": path.is_dir(), "tree": _tree(path)}
 86	
 87	    candidates: list[dict[str, object]] = []
 88	    seen: set[str] = set()
 89	    search_bases = [output_dir, output_dir.parent, requirements_dir, requirements_dir.parent, Path.cwd()]
 90	    for base in search_bases:
 91	        for name in INTERESTING_DIRS:
 92	            for candidate in (base / name, base / "backend" / name):
 93	                key = str(candidate)
 94	                if key in seen or not candidate.is_dir():
 95	                    continue
 96	                seen.add(key)
 97	                spec_count = 0
 98	                for pattern in ("**/*.spec.js", "**/*.spec.ts", "**/*.test.js", "**/*.test.ts"):
 99	                    try:
100	                        spec_count += sum(1 for _ in candidate.glob(pattern))
101	                    except OSError:
102	                        pass
103	                candidates.append(
104	                    {
105	                        "path": key,
106	                        "spec_files": spec_count,
107	                        "has_package_json": (candidate / "package.json").is_file(),
108	                        "has_playwright_config": any(candidate.glob("playwright.config.*")),
109	                    }
110	                )
111	    return {"roots": roots, "test_candidates": candidates}
112	
113	
114	def write_recon(output_dir: Path, requirements_dir: Path) -> Path:
115	    payload = {
116	        "environment": environment_snapshot(),
117	        "directories": directory_recon(output_dir, requirements_dir),
118	    }
119	    target = output_dir / ".arc-factory" / "recon.json"
120	    target.parent.mkdir(parents=True, exist_ok=True)
121	    target.write_text(json.dumps(payload, ensure_ascii=False, indent=2)[:2_000_000], encoding="utf-8")
122	    return target

